/**
 * ATTENTION! This class is used internally in Large KinFu.
 * It has been pushed to publicly available headers for tests only.
 * Source compatibility of this API is not guaranteed in the future.
 * This class provides tools to solve so-called pose graph problem often arisen in SLAM problems
 * The pose graph format, cost function and optimization techniques
 * repeat the ones used in Ceres 3D Pose Graph Optimization:
 * http://ceres-solver.org/nnls_tutorial.html#other-examples, pose_graph_3d.cc bullet
 *
 * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/detail/pose_graph.hpp#L26
 */
export interface detail_PoseGraph extends Omit<ClassHandle, 'clone'> {
  readonly [nativeType]: ClassHandle[typeof nativeType] & { detail_PoseGraph: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
}

/**
 * odometry type in the OpenCV API.
 *
 * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry.hpp#L38
 */
export interface Odometry extends Omit<ClassHandle, 'compute1' | 'compute2' | 'getNormalsComputer' | 'prepareFrame' | 'prepareFrames' | 'compute' | 'clone'> {
  readonly [nativeType]: ClassHandle[typeof nativeType] & { Odometry: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
  /**
   * Compute Rigid Transformation between two frames so that Rt * src = dst
   *
   * @param srcDepth source depth ("original" image)
   *
   * @param dstDepth destination depth ("rotated" image)
   *
   * @param Rt Output destination, filled by the native operation. Rigid transformation, which will be calculated, in form:
   * { R_11 R_12 R_13 t_1
   *   R_21 R_22 R_23 t_2
   *   R_31 R_32 R_33 t_3
   *   0    0    0    1  }
   *
   * @returns true on success, false if failed to find the transformation
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry.hpp#L82
   */
  compute1(srcDepth: Mat, dstDepth: Mat, Rt: Mat): boolean;
  /**
   * Compute Rigid Transformation between two frames so that Rt * src = dst
   *
   * @param srcDepth source depth ("original" image)
   *
   * @param srcRGB source RGB
   *
   * @param dstDepth destination depth ("rotated" image)
   *
   * @param dstRGB destination RGB
   *
   * @param Rt Output destination, filled by the native operation. Rigid transformation, which will be calculated, in form:
   * { R_11 R_12 R_13 t_1
   *   R_21 R_22 R_23 t_2
   *   R_31 R_32 R_33 t_3
   *   0    0    0    1  }
   *
   * @returns true on success, false if failed to find the transformation
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry.hpp#L97
   */
  compute2(srcDepth: Mat, srcRGB: Mat, dstDepth: Mat, dstRGB: Mat, Rt: Mat): boolean;
  /**
   * Get the normals computer object used for normals calculation (if presented).
   * The normals computer is generated at first need during prepareFrame when normals are required for the ICP algorithm
   * but not presented by a user. Re-generated each time the related settings change or a new frame arrives with the different size.
   *
   * @returns The RgbdNormals | null result.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry.hpp#L104
   */
  getNormalsComputer(): RgbdNormals | null;
  /**
   * Prepare frame for odometry calculation
   *
   * @param frame odometry prepare this frame as src frame and dst frame simultaneously
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry.hpp#L49
   */
  prepareFrame(frame: OdometryFrame): void;
  /**
   * Prepare frame for odometry calculation
   *
   * @param srcFrame frame will be prepared as src frame ("original" image)
   *
   * @param dstFrame frame will be prepared as dsr frame ("rotated" image)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry.hpp#L55
   */
  prepareFrames(srcFrame: OdometryFrame, dstFrame: OdometryFrame): void;
  /**
   * Compute Rigid Transformation between two frames so that Rt * src = dst
   * Both frames, source and destination, should have been prepared by calling prepareFrame() first
   *
   * @param srcFrame src frame ("original" image)
   *
   * @param dstFrame dst frame ("rotated" image)
   *
   * @param Rt Output destination, filled by the native operation. Rigid transformation, which will be calculated, in form:
   * { R_11 R_12 R_13 t_1
   *   R_21 R_22 R_23 t_2
   *   R_31 R_32 R_33 t_3
   *   0    0    0    1  }
   *
   * @returns true on success, false if failed to find the transformation
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry.hpp#L69
   */
  compute(srcFrame: OdometryFrame, dstFrame: OdometryFrame, Rt: Mat): boolean;
}

/**
 * An object that keeps per-frame data for Odometry algorithms from user-provided images to algorithm-specific precalculated data.
 * When not empty, it contains a depth image, a mask of valid pixels and a set of pyramids generated from that data.
 * A BGR/Gray image and normals are optional.
 * OdometryFrame is made to be used together with Odometry class to reuse precalculated data between Rt data calculations.
 * A correct way to do that is to call Odometry::prepareFrames() on prev and next frames and then pass them to Odometry::compute() method.
 *
 * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L36
 */
export interface OdometryFrame extends Omit<ClassHandle, 'getImage' | 'getGrayImage' | 'getDepth' | 'getProcessedDepth' | 'getMask' | 'getNormals' | 'getPyramidLevels' | 'getPyramidAt' | 'clone'> {
  readonly [nativeType]: ClassHandle[typeof nativeType] & { OdometryFrame: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
  /**
   * Get the original user-provided BGR/Gray image
   *
   * @param image Output destination, filled by the native operation. Output image
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L57
   */
  getImage(image: Mat): void;
  /**
   * Get the gray image generated from the user-provided BGR/Gray image
   *
   * @param image Output destination, filled by the native operation. Output image
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L63
   */
  getGrayImage(image: Mat): void;
  /**
   * Get the original user-provided depth image
   *
   * @param depth Output destination, filled by the native operation. Output image
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L69
   */
  getDepth(depth: Mat): void;
  /**
   * Get the depth image generated from the user-provided one after conversion, rescale or filtering for ICP algorithm needs
   *
   * @param depth Output destination, filled by the native operation. Output image
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L75
   */
  getProcessedDepth(depth: Mat): void;
  /**
   * Get the valid pixels mask generated for the ICP calculations intersected with the user-provided mask
   *
   * @param mask Output destination, filled by the native operation. Output image
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L81
   */
  getMask(mask: Mat): void;
  /**
   * Get the normals image either generated for the ICP calculations or user-provided
   *
   * @param normals Output destination, filled by the native operation. Output image
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L87
   */
  getNormals(normals: Mat): void;
  /**
   * Get the amount of levels in pyramids (all of them if not empty should have the same number of levels)
   * or 0 if no pyramids were prepared yet
   *
   * @returns The number result.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L93
   */
  getPyramidLevels(): number;
  /**
   * Get the image generated for the ICP calculations from one of the pyramids specified by pyrType. Returns empty image if
   * the pyramid is empty or there's no such pyramid level
   *
   * @param img Output destination, filled by the native operation. Output image
   *
   * @param pyrType Type of pyramid
   *
   * @param level Level in the pyramid
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/ptcloud/include/opencv2/ptcloud/odometry_frame.hpp#L102
   */
  getPyramidAt(img: Mat, pyrType: number, level: number): void;
}

