/**
 * Base class for modelling a Map between two images.
 *
 * The class is only used to define the common interface for any possible map.
 *
 * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/reg/include/opencv2/reg/map.hpp#L124
 */
export interface reg_Map extends Omit<ClassHandle, 'warp' | 'inverseWarp' | 'inverseMap' | 'compose' | 'scale' | 'clone'> {
  readonly [nativeType]: ClassHandle[typeof nativeType] & { reg_Map: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
  /**
   * Warps image to a new coordinate frame. The calculation is img2(x)=img1(T^{-1}(x)), as we
   * have to apply the inverse transformation to the points to move them to were the values
   * of img2 are.
   *
   * @param img1 Original image
   *
   * @param img2 Output destination, filled by the native operation. Warped image
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/reg/include/opencv2/reg/map.hpp#L139
   */
  warp(img1: Mat, img2: Mat): void;
  /**
   * Warps image to a new coordinate frame. The calculation is img2(x)=img1(T(x)), so in fact
   * this is the inverse warping as we are taking the value of img1 with the forward
   * transformation of the points.
   *
   * @param img1 Original image
   *
   * @param img2 Output destination, filled by the native operation. Warped image
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/reg/include/opencv2/reg/map.hpp#L148
   */
  inverseWarp(img1: Mat, img2: Mat): void;
  /**
   * Calculates the inverse map
   *
   * @returns Inverse map
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/reg/include/opencv2/reg/map.hpp#L154
   */
  inverseMap(): reg_Map | null;
  /**
   * Changes the map composing the current transformation with the one provided in the call.
   * The order is first the current transformation, then the input argument.
   *
   * @param map Transformation to compose with.
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/reg/include/opencv2/reg/map.hpp#L161
   */
  compose(map: reg_Map | null): void;
  /**
   * Scales the map by a given factor as if the coordinates system is expanded/compressed
   * by that factor.
   *
   * @param factor Expansion if bigger than one, compression if smaller than one
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/reg/include/opencv2/reg/map.hpp#L168
   */
  scale(factor: number): void;
}

