/**
 * Class, allowing the load and matching 3D models.
 * Typical Use:
 *
 * ```cpp
 * // Train a model
 * ppf_match_3d::PPF3DDetector detector(0.05, 0.05);
 * detector.trainModel(pc);
 * // Search the model in a given scene
 * vector<Pose3DPtr> results;
 * detector.match(pcTest, results, 1.0/5.0,0.05);
 *
 * ```
 *
 * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/surface_matching/include/opencv2/surface_matching/ppf_match_3d.hpp#L97
 */
export interface ppf_match_3d_PPF3DDetector extends Omit<ClassHandle, 'trainModel' | 'match' | 'clone'> {
  readonly [nativeType]: ClassHandle[typeof nativeType] & { ppf_match_3d_PPF3DDetector: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
  /**
   * Trains a new model.
   *
   * @param Model The input point cloud with normals (Nx6)
   *
   *  Uses the parameters set in the constructor to downsample and learn a new model. When the model is learnt, the instance gets ready for calling "match".
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/surface_matching/include/opencv2/surface_matching/ppf_match_3d.hpp#L131
   */
  trainModel(Model: Mat): void;
  /**
   * Matches a trained model across a provided scene.
   *
   * @param scene Point cloud for the scene
   *
   * @param results Output destination, filled by the native operation. List of output poses
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/surface_matching/include/opencv2/surface_matching/ppf_match_3d.hpp#L141
   */
  match(scene: Mat, results: Ptr_cv__ppf_match_3d__Pose3DVector): void;
  /**
   * Matches a trained model across a provided scene.
   *
   * @param scene Point cloud for the scene
   *
   * @param results Output destination, filled by the native operation. List of output poses
   *
   * @param relativeSceneSampleStep The ratio of scene points to be used for the matching after sampling with relativeSceneDistance. For example, if this value is set to 1.0/5.0, every 5th point from the scene is used for pose estimation. This parameter allows an easy trade-off between speed and accuracy of the matching. Increasing the value leads to less points being used and in turn to a faster but less accurate pose computation. Decreasing the value has the inverse effect.
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/surface_matching/include/opencv2/surface_matching/ppf_match_3d.hpp#L141
   */
  match(scene: Mat, results: Ptr_cv__ppf_match_3d__Pose3DVector, relativeSceneSampleStep: number): void;
  /**
   * Matches a trained model across a provided scene.
   *
   * @param scene Point cloud for the scene
   *
   * @param results Output destination, filled by the native operation. List of output poses
   *
   * @param relativeSceneSampleStep The ratio of scene points to be used for the matching after sampling with relativeSceneDistance. For example, if this value is set to 1.0/5.0, every 5th point from the scene is used for pose estimation. This parameter allows an easy trade-off between speed and accuracy of the matching. Increasing the value leads to less points being used and in turn to a faster but less accurate pose computation. Decreasing the value has the inverse effect.
   *
   * @param relativeSceneDistance Set the distance threshold relative to the diameter of the model. This parameter is equivalent to relativeSamplingStep in the training stage. This parameter acts like a prior sampling with the relativeSceneSampleStep parameter.
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/surface_matching/include/opencv2/surface_matching/ppf_match_3d.hpp#L141
   */
  match(scene: Mat, results: Ptr_cv__ppf_match_3d__Pose3DVector, relativeSceneSampleStep: number, relativeSceneDistance: number): void;
}

