  readonly [nativeType]: ClassHandle[typeof nativeType] & { dnn_Net: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
  /**
   * Returns true if there are no layers in the network.
   *
   * @returns The boolean result.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/dnn/include/opencv2/dnn/dnn.hpp#L592
   */
  empty(): boolean;
  /**
   * Dump net to String
   *
   * @returns String with structure, hyperparameters, backend, target and fusion
   *  Call method after setInput(). To see correct backend, target and fusion run after forward().
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/dnn/include/opencv2/dnn/dnn.hpp#L598
   */
