/**
 * barcode barcode detector type in the OpenCV API.
 *
 * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L18
 */
export interface barcode_BarcodeDetector extends Omit<GraphicalCodeDetector, 'decodeWithType' | 'detectAndDecodeWithType' | 'getDownsamplingThreshold' | 'setDownsamplingThreshold' | 'getDetectorScales' | 'setDetectorScales' | 'getGradientThreshold' | 'setGradientThreshold' | 'clone'> {
  readonly [nativeType]: GraphicalCodeDetector[typeof nativeType] & { barcode_BarcodeDetector: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
  /**
   * Decodes barcode in image once it's found by the detect() method.
   *
   * @param img grayscale or color (BGR) image containing bar code.
   *
   * @param points vector of rotated rectangle vertices found by detect() method (or some other algorithm).
   * For N detected barcodes, the dimensions of this array should be [N][4].
   * Order of four points in vector<Point2f> is bottomLeft, topLeft, topRight, bottomRight.
   *
   * @param decoded_info Output destination, filled by the native operation. UTF8-encoded output vector of string or empty vector of string if the codes cannot be decoded.
   *
   * @param decoded_type Output destination, filled by the native operation. vector strings, specifies the type of these barcodes
   *
   * @returns true if at least one valid barcode have been found
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L49
   */
  decodeWithType(img: Mat, points: Mat, decoded_info: StringVector, decoded_type: StringVector): boolean;
  /**
   * Both detects and decodes barcode
   *
   * @param img grayscale or color (BGR) image containing barcode.
   *
   * @param decoded_info Output destination, filled by the native operation. UTF8-encoded output vector of string(s) or empty vector of string if the codes cannot be decoded.
   *
   * @param decoded_type Output destination, filled by the native operation. vector of strings, specifies the type of these barcodes
   *
   * @returns true if at least one valid barcode have been found
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L62
   */
  detectAndDecodeWithType(img: Mat, decoded_info: StringVector, decoded_type: StringVector): boolean;
  /**
   * Both detects and decodes barcode
   *
   * @param img grayscale or color (BGR) image containing barcode.
   *
   * @param decoded_info Output destination, filled by the native operation. UTF8-encoded output vector of string(s) or empty vector of string if the codes cannot be decoded.
   *
   * @param decoded_type Output destination, filled by the native operation. vector of strings, specifies the type of these barcodes
   *
   * @param points Output destination, filled by the native operation. optional output vector of vertices of the found  barcode rectangle. Will be empty if not found.
   *
   * @returns true if at least one valid barcode have been found
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L62
   */
  detectAndDecodeWithType(img: Mat, decoded_info: StringVector, decoded_type: StringVector, points: Mat): boolean;
  /**
   * Get detector downsampling threshold.
   *
   * @returns detector downsampling threshold
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L71
   */
  getDownsamplingThreshold(): number;
  /**
   * Set detector downsampling threshold.
   *
   * By default, the detect method resizes the input image to this limit if the smallest image size is is greater than the threshold.
   * Increasing this value can improve detection accuracy and the number of results at the expense of performance.
   * Correlates with detector scales. Setting this to a large value will disable downsampling.
   *
   * See: setDetectorScales
   *
   * @param thresh downsampling limit to apply (default 512)
   *
   * @returns The barcode_BarcodeDetector result.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L81
   */
  setDownsamplingThreshold(thresh: number): barcode_BarcodeDetector;
  /**
   * Returns detector box filter sizes.
   *
   * @param sizes Output destination, filled by the native operation. output parameter for returning the sizes.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L87
   */
  getDetectorScales(sizes: FloatVector): void;
  /**
   * Set detector box filter sizes.
   *
   * Adjusts the value and the number of box filters used in the detect step.
   * The filter sizes directly correlate with the expected line widths for a barcode. Corresponds to expected barcode distance.
   * If the downsampling limit is increased, filter sizes need to be adjusted in an inversely proportional way.
   *
   * @param sizes box filter sizes, relative to minimum dimension of the image (default [0.01, 0.03, 0.06, 0.08])
   *
   * @returns The barcode_BarcodeDetector result.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L96
   */
  setDetectorScales(sizes: FloatVector): barcode_BarcodeDetector;
  /**
   * Get detector gradient magnitude threshold.
   *
   * @returns detector gradient magnitude threshold.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L102
   */
  getGradientThreshold(): number;
  /**
   * Set detector gradient magnitude threshold.
   *
   * Sets the coherence threshold for detected bounding boxes.
   * Increasing this value will generate a closer fitted bounding box width and can reduce false-positives.
   * Values between 16 and 1024 generally work, while too high of a value will remove valid detections.
   *
   * @param thresh gradient magnitude threshold (default 64).
   *
   * @returns The barcode_BarcodeDetector result.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/objdetect/include/opencv2/objdetect/barcode.hpp#L111
   */
  setGradientThreshold(thresh: number): barcode_BarcodeDetector;
}

