  /**
   * predicted state (x'(k)): x(k)=A*x(k-1)+B*u(k)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L563
   */
  statePre: Mat;
  /**
   * corrected state (x(k)): x(k)=x'(k)+K(k)*(z(k)-H*x'(k))
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L564
   */
  statePost: Mat;
  /**
   * state transition matrix (A)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L565
   */
  transitionMatrix: Mat;
  /**
   * control matrix (B) (not used if there is no control)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L566
   */
  controlMatrix: Mat;
  /**
   * measurement matrix (H)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L567
   */
  measurementMatrix: Mat;
  /**
   * process noise covariance matrix (Q)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L568
   */
  processNoiseCov: Mat;
  /**
   * measurement noise covariance matrix (R)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L569
   */
  measurementNoiseCov: Mat;
  /**
   * priori error estimate covariance matrix (P'(k)): P'(k)=A*P(k-1)*At + Q)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L570
   */
  errorCovPre: Mat;
  /**
   * Kalman gain matrix (K(k)): K(k)=P'(k)*Ht*inv(H*P'(k)*Ht+R)
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/video/include/opencv2/video/tracking.hpp#L571
   */
