/**
 * Class implementing Signature Quadratic Form Distance (SQFD).
 * See: Christian Beecks, Merih Seran Uysal, Thomas Seidl.
 *   Signature quadratic form distance.
 *   In Proceedings of the ACM International Conference on Image and Video Retrieval, pages 438-445.
 *   ACM, 2010.
 * [BeecksUS10]
 *
 * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/xfeatures2d/include/opencv2/xfeatures2d.hpp#L1034
 */
export interface xfeatures2d_PCTSignaturesSQFD extends Omit<Algorithm, 'computeQuadraticFormDistance' | 'computeQuadraticFormDistances' | 'clone'> {
  readonly [nativeType]: Algorithm[typeof nativeType] & { xfeatures2d_PCTSignaturesSQFD: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
  /**
   * Computes Signature Quadratic Form Distance of two signatures.
   *
   * @param _signature0 The first signature.
   *
   * @param _signature1 The second signature.
   *
   * @returns The number result.
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/xfeatures2d/include/opencv2/xfeatures2d.hpp#L1057
   */
  computeQuadraticFormDistance(_signature0: Mat, _signature1: Mat): number;
  /**
   * Computes Signature Quadratic Form Distance between the reference signature
   *       and each of the other image signatures.
   *
   * @param sourceSignature The signature to measure distance of other signatures from.
   *
   * @param imageSignatures Vector of signatures to measure distance from the source signature.
   *
   * @param distances Output vector of measured distances.
   *
   * @see https://github.com/opencv/opencv_contrib/blob/5.0.0/modules/xfeatures2d/include/opencv2/xfeatures2d.hpp#L1068
   */
  computeQuadraticFormDistances(sourceSignature: Mat, imageSignatures: MatVector, distances: FloatVector): void;
}

