/**
 * Base class for all blenders.
 *
 * Simple blender which puts one image over another
 *
 * @see https://github.com/opencv/opencv/blob/5.0.0/modules/stitching/include/opencv2/stitching/detail/blenders.hpp#L63
 */
export interface detail_Blender extends Omit<ClassHandle, 'prepare' | 'prepare1' | 'feed' | 'blend' | 'clone'> {
  readonly [nativeType]: ClassHandle[typeof nativeType] & { detail_Blender: true };
  /**
   * Create another handle to the same native object. This retains the object without copying its pixels or algorithm state; dispose both handles separately.
   *
   * @returns The this result.
   */
  clone(): this;
  /**
   * Prepares the blender for blending.
   *
   * @param corners Source images top-left corners
   *
   * @param sizes Source image sizes
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/stitching/include/opencv2/stitching/detail/blenders.hpp#L76
   */
  prepare(corners: PointVector, sizes: SizeVector): void;
  /**
   * Prepares the blender for blending.
   *
   * @param dst_roi dst roi argument (Rect).
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/stitching/include/opencv2/stitching/detail/blenders.hpp#L78
   */
  prepare1(dst_roi: Rect): void;
  /**
   * Processes the image.
   *
   * @param img Source image
   *
   * @param mask Source image mask
   *
   * @param tl Source image top-left corners
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/stitching/include/opencv2/stitching/detail/blenders.hpp#L85
   */
  feed(img: Mat, mask: Mat, tl: Point): void;
  /**
   * Blends and returns the final pano.
   *
   * @param dst Input/output value, modified by the native operation. Final pano
   *
   * @param dst_mask Input/output value, modified by the native operation. Final pano mask
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/stitching/include/opencv2/stitching/detail/blenders.hpp#L91
   */
  blend(dst: Mat, dst_mask: Mat): void;
}

