  /**
   * Shape matching methods
   *
   * `A` denotes object1,`B` denotes object2
   *
   * `\begin{array}{l} m^A_i =  \mathrm{sign} (h^A_i)  \cdot \log{h^A_i} \\ m^B_i =  \mathrm{sign} (h^B_i)  \cdot \log{h^B_i} \end{array}`
   *
   * and `h^A_i, h^B_i` are the Hu moments of `A` and `B` , respectively.
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/imgproc/include/opencv2/imgproc.hpp#L449
   */
  ShapeMatchModes: {
  /**
   * ```math
   * I_1(A,B) =  \sum _{i=1...7}  \left |  \frac{1}{m^A_i} -  \frac{1}{m^B_i} \right |
   * ```
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/imgproc/include/opencv2/imgproc.hpp#L450
   */
  CONTOURS_MATCH_I1: ShapeMatchModesValue<1>, 
  /**
   * ```math
   * I_2(A,B) =  \sum _{i=1...7}  \left | m^A_i - m^B_i  \right |
   * ```
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/imgproc/include/opencv2/imgproc.hpp#L451
   */
  CONTOURS_MATCH_I2: ShapeMatchModesValue<2>, 
  /**
   * ```math
   * I_3(A,B) =  \max _{i=1...7}  \frac{ \left| m^A_i - m^B_i \right| }{ \left| m^A_i \right| }
   * ```
   *
   * @see https://github.com/opencv/opencv/blob/5.0.0/modules/imgproc/include/opencv2/imgproc.hpp#L452
   */
  CONTOURS_MATCH_I3: ShapeMatchModesValue<3>};
