/**
 * The initialized native WASM module, including its virtual filesystem and memory views. createOpenCV adds typed namespaces and JavaScript helpers.
 */
export type MainModule = WasmModule & typeof RuntimeExports & EmbindModule;
export default function MainModuleFactory (options?: unknown): Promise<MainModule>;

/** Graph inputs and outputs supported by the native graph executor. */
export type GraphValue = Mat | Scalar | number | bigint | boolean | string | Point | Point2f | Point3f | Size | Rect | readonly (Mat | Scalar | number | bigint | boolean | string | Point | Point2f | Point3f | Size | Rect | GDrawPrim)[]
/**
 * A placeholder describing an input, intermediate value or output of a native graph. Supply runtime values to GComputation.apply instead of passing these nodes as pixel data.
 */
export type GraphNode = GOpaque_int | GOpaque_double | GArray_int | GArray_Point2f | GArray_Point3f | GOpaque_Rect | GArray_Point2i | GArray_Rect | GOpaque_Size | GArray_uint64_t | GArray_Prim | GArray_int64_t | GOpaque_int64_t | GArray_double | GArray_float | GOpaque_float | GOpaque_uint64_t | GArray_bool | GOpaque_bool | GArray_string | GOpaque_string | GOpaque_Point | GOpaque_Point2f | GOpaque_Point3f | GArray_Size | GArray_Mat | GArray_Scalar | GFrame | GMat | GScalar

/** CPU drawing primitives accepted by the G-API renderer. */
export type DrawPrimitive = gapi_wip_draw_Text | gapi_wip_draw_Rect | gapi_wip_draw_Circle | gapi_wip_draw_Line | gapi_wip_draw_Mosaic | gapi_wip_draw_Image | gapi_wip_draw_Poly

